import json
import shutil
import subprocess
import time
from pathlib import Path
LINT_BIN = 'vault-lint'
SCAN_TIMEOUT = 300
TRASH_DIRNAME = '.trash'


def _move_to_trash(vault: Path, path: Path) -> Path:
    # Relocate the orphan into the vault's trash folder, preserving its relative layout
    stamp = time.strftime('%Y%m%d-%H%M%S')
    dest = vault / TRASH_DIRNAME / stamp / path.relative_to(vault)
    dest.parent.mkdir(parents=True, exist_ok=True)
    shutil.move(str(path), str(dest))
    return dest


def purge_orphaned_attachments(vault_dir: str, dry_run: bool=False) -> dict:
    vault = Path(vault_dir).expanduser().resolve()
    attachments_dir = vault / 'attachments'
    if not attachments_dir.is_dir():
        return {'ok': False, 'error': f'No attachments folder in {vault}'}
    cmd = [LINT_BIN, 'orphans', '--vault', str(vault), '--kind', 'attachments', '--format', 'json']
    with subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True) as proc:
        try:
            stdout, stderr = proc.communicate(timeout=SCAN_TIMEOUT)
        except subprocess.TimeoutExpired:
            proc.kill()
            return {'ok': False, 'error': 'vault-lint scan timed out'}
        if proc.returncode != 0:
            return {'ok': False, 'error': stderr.strip() or f'vault-lint exited {proc.returncode}'}
    try:
        orphans = json.loads(stdout).get('orphans', [])
    except json.JSONDecodeError:
        return {'ok': False, 'error': 'Could not parse vault-lint output'}
    candidates = []
    for rel in orphans:
        path = (vault / rel).resolve()
        if attachments_dir in path.parents and path.is_file():
            candidates.append(path)
    if dry_run:
        return {'ok': True, 'dry_run': True, 'orphans': [p.relative_to(vault).as_posix() for p in candidates]}
    deleted, failed = ([], [])
    freed = 0
    for path in candidates:
        try:
            size = path.stat().st_size
            _move_to_trash(vault, path)
            freed += size
            deleted.append(path.relative_to(vault).as_posix())
        except OSError as exc:
            failed.append({'path': path.relative_to(vault).as_posix(), 'error': str(exc)})
    return {'ok': not failed, 'dry_run': False, 'deleted': deleted, 'failed': failed, 'bytes_freed': freed}
